import { describe, test, expect } from "vitest";
import PQueue from "../source/index.js";

describe("p-queue signal abort while queued", () => {
  test("aborting signal while task is queued should reject the task and remove it from the queue", async () => {
    const queue = new PQueue({ concurrency: 1 });

    // First task: takes a long time, occupies the only concurrency slot
    let firstTaskStarted = false;
    const firstTaskPromise = queue.add(async () => {
      firstTaskStarted = true;
      await new Promise(resolve => setTimeout(resolve, 100));
      return "first";
    });

    // Second task: gets queued because first is running
    const controller = new AbortController();
    let secondTaskExecuted = false;
    const secondTaskPromise = queue.add(async () => {
      secondTaskExecuted = true;
      return "second";
    }, { signal: controller.signal });

    // Wait a bit to make sure the second task is in the queue
    await new Promise(resolve => setTimeout(resolve, 10));
    expect(queue.size).toBe(1);
    expect(firstTaskStarted).toBe(true);

    // Abort the second task
    controller.abort();

    // The second task should be rejected and removed from the queue
    await expect(secondTaskPromise).rejects.toThrow();
    expect(queue.size).toBe(0);
    expect(secondTaskExecuted).toBe(false);

    // First task should still complete normally
    await firstTaskPromise;
  });
});
